mapper.select:
SELECT schedule_slot_id, doctor_id, schedule_date, slot_period, slot_status, created_at, updated_at
FROM schedule_slots
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND slot_period = #{slotPeriod}

mapper.update:
UPDATE schedule_slots
SET slot_status = 'BOOKED'
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND slot_period = #{slotPeriod}
  AND slot_status = 'AVAILABLE'

mapper.select:
SELECT schedule_slot_id, doctor_id, schedule_date, slot_period, slot_status, created_at, updated_at
FROM schedule_slots WHERE doctor_id = #{doctorId} AND schedule_date = #{scheduleDate}
ORDER BY schedule_slot_id FOR UPDATE

